let recipeCatalogue=[];let catalogueLoaded=false;let stockSuggestionMode=false;
const CATALOG_CSV='https://raw.githubusercontent.com/josephrmartinez/recipe-dataset/main/13k-recipes.csv';
function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field);rows.push(row);row=[];field=''}else if(c!=='\r')field+=c}if(field.length||row.length){row.push(field);rows.push(row)}return rows}
function parseCatalogRow(row,headers,index){let get=k=>row[headers.indexOf(k)]||'';let title=get('Title')||get('title')||row[1]||'';let rawIng=get('Ingredients')||get('ingredients')||row[2]||'';let instructions=get('Instructions')||get('instructions')||row[3]||'';if(!title.trim())return null;let parts=rawIng.replace(/^\s*\[|\]\s*$/g,'').split(/,(?=(?:[^']*'[^']*')*[^']*$)/).map(x=>x.replace(/^\s*['"]|['"]\s*$/g,'').trim()).filter(Boolean);let ingredients=parts.map(x=>{let m=x.match(/^(\d+(?:[./]\d+)?(?:\s*\d+\/\d+)?)\s*(.*)$/);let amount=1,name=x;if(m){let v=m[1].trim();amount=v.includes('/')?(()=>{let a=v.split(/\s+/);let z=a.pop().split('/');return (a.length?+a[0]:0)+(+z[0]/+z[1])})():parseFloat(v);name=m[2]||x}return [name.toLowerCase(),Number.isFinite(amount)&&amount>0?amount:1,'portion']});let steps=instructions.split(/(?<=[.!?])\s+|\n+/).map(x=>x.trim()).filter(Boolean);return {id:'epic-'+index,name:title.trim(),minutes:0,category:'Cuisine internationale',ingredients,steps:steps.length?steps:['Consulte la source pour les instructions détaillées.'],nutrition:{},source:'https://github.com/josephrmartinez/recipe-dataset',provider:'Epicurious · CC BY-SA 3.0'}}
async function loadRecipeCatalogue(){let hint=$('cataloghint'),btn=$('catalogload'),bar=$('catalogprogress');if(catalogueLoaded){hint.textContent='Catalogue déjà chargé : '+recipeCatalogue.length+' recettes.';return}btn.disabled=true;btn.textContent='Chargement…';hint.textContent='Téléchargement du catalogue (environ 26 Mo)…';try{let res=await fetch(CATALOG_CSV);if(!res.ok)throw new Error('Téléchargement impossible');let csv=await res.text();bar.style.width='55%';hint.textContent='Lecture et indexation des recettes…';let rows=parseCSV(csv);let headers=rows.shift().map(x=>x.trim());recipeCatalogue=rows.slice(0,5000).map((r,i)=>parseCatalogRow(r,headers,i+1)).filter(Boolean);catalogueLoaded=true;bar.style.width='100%';hint.textContent=recipeCatalogue.length+' recettes chargées. Tu peux maintenant les rechercher et les filtrer.';btn.textContent='Catalogue chargé';$('catalogcount').textContent=recipeCatalogue.length+' recettes';renderRecipes()}catch(e){hint.textContent='Le catalogue n’a pas pu être téléchargé. Vérifie la connexion et réessaie. Tes données existantes ne sont pas touchées.';btn.textContent='Réessayer';btn.disabled=false}}
function storeExternalRecipe(r){let existing=db.recipes.find(x=>x.id===r.id);if(!existing){db.recipes.push(r);localStorage.setItem(KEY,JSON.stringify(db))}return existing||r}
let db=JSON.parse(localStorage.getItem(KEY)||'{}');db.foods??=[];db.courses??=[];db.history??=[];db.spend??=[];db.budget??=0;db.recipes??=[];if(!db.recipes.length)db.recipes=seedRecipes.map(r=>({...r}));db.favorites??=[];db.plans??=[];db.shoppingDate??='';db.recipeProxyUrl??='';
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function log(t){db.history.unshift({t,at:new Date().toLocaleString('fr-CH')});db.history=db.history.slice(0,150)}
function save(){db.budget=+$('budget')?.value||db.budget;localStorage.setItem(KEY,JSON.stringify(db));render()}
function show(id,btn){document.querySelectorAll('main section').forEach(s=>s.classList.toggle('hidden',s.id!==id));document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id!=='recipes'&&pickerDay===null)$('pickerback')?.classList.add('hidden');render()}
function days(d){if(!d)return 999;return Math.ceil((new Date(d+'T00:00:00')-new Date(new Date().toDateString()))/86400000)}
$('today').textContent=new Date().toLocaleDateString('fr-CH',{weekday:'short',day:'numeric',month:'short'});
$('foodform').onsubmit=async e=>{e.preventDefault();let photo='';const f=$('fphoto').files[0];if(f)photo=await new Promise(r=>{let x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(f)});db.foods.push({id:Date.now(),name:$('fname').value,qty:+$('fqty').value||1,unit:$('funit').value,place:$('fplace').value,date:$('fdate').value,photo});log('Aliment ajouté : '+$('fname').value);e.target.reset();save()};
$('courseform').onsubmit=e=>{e.preventDefault();db.courses.push({id:Date.now(),name:$('cname').value,qty:$('cqty').value,store:$('store').value,manual:true});log('Ajout aux courses : '+$('cname').value);e.target.reset();save()};
