// Mealora 5.14 — controlled packaging review. No product enters stock before explicit confirmation.
let packageCandidates=[];
function openPackageReview(){
 packageCandidates=[
  {name:'Pâtes penne',qty:'500',unit:'g',checked:true},
  {name:'Riz basmati',qty:'1',unit:'kg',checked:true},
  {name:'Tomates concassées',qty:'400',unit:'g',checked:true},
  {name:'Haricots rouges',qty:'400',unit:'g',checked:true}
 ];
 $('packagephotos').value='';$('packagephotoNames').textContent='';$('packageplace').value='Armoire';renderPackageCandidates();$('packagereview').showModal();
}
function closePackageReview(){$('packagereview').close()}
function renderPackageCandidates(){
 $('packagecandidates').innerHTML=packageCandidates.map((p,i)=>`<div class="detailbox"><div class="row" style="align-items:center"><label style="display:flex;align-items:center;gap:8px;flex:0 0 auto"><input type="checkbox" style="width:auto;margin:0" ${p.checked?'checked':''} onchange="packageCandidates[${i}].checked=this.checked"> À ajouter</label><b style="flex:1">Produit ${i+1}</b></div><label>Nom du produit</label><input value="${esc(p.name)}" oninput="packageCandidates[${i}].name=this.value"><div class="row"><div><label>Quantité</label><input type="number" min="0.001" step="any" value="${esc(p.qty)}" oninput="packageCandidates[${i}].qty=this.value"></div><div><label>Unité</label><select onchange="packageCandidates[${i}].unit=this.value">${['g','kg','ml','l','pièce','paquet'].map(u=>`<option ${p.unit===u?'selected':''}>${u}</option>`).join('')}</select></div></div><label>Date limite (facultative)</label><input type="date" value="${esc(p.date||'')}" onchange="packageCandidates[${i}].date=this.value"></div>`).join('');
}
$('packagephotos').addEventListener('change',e=>{$('packagephotoNames').textContent=[...e.target.files].map(f=>f.name).join(' · ')||'Aucune photo sélectionnée';});
function confirmPackageProducts(){
 const selected=packageCandidates.filter(p=>p.checked);
 if(!selected.length)return alert('Sélectionne au moins un produit.');
 for(const p of selected){const qty=Number(String(p.qty).replace(',','.'));if(!p.name.trim()||!Number.isFinite(qty)||qty<=0)return alert('Vérifie le nom et la quantité de chaque produit sélectionné.');}
 const place=$('packageplace').value;
 selected.forEach(p=>{const qty=Number(String(p.qty).replace(',','.'));const existing=db.foods.find(f=>normIngredient(f.name)===normIngredient(p.name)&&norm(f.unit)===norm(p.unit)&&norm(f.place)===norm(place));if(existing){existing.qty=(Number(existing.qty)||0)+qty;if(p.date)existing.date=p.date;}else db.foods.push({id:Date.now()+Math.random(),name:p.name.trim(),qty,unit:p.unit,place,date:p.date||'',photo:''});});
 log('Produits confirmés et ajoutés au stock : '+selected.map(p=>p.name+' '+p.qty+' '+p.unit).join(', '));localStorage.setItem(KEY,JSON.stringify(db));closePackageReview();render();show('stock');
}

function removeFood(id){let f=db.foods.find(x=>x.id===id);db.foods=db.foods.filter(x=>x.id!==id);log('Aliment supprimé : '+f?.name);save()}
function editFood(id){let f=db.foods.find(x=>String(x.id)===String(id));if(!f)return;let name=prompt('Nom de l’aliment',f.name);if(name===null)return;let qty=prompt('Quantité en stock',String(f.qty));if(qty===null)return;let unit=prompt('Unité (pièce, g, kg, ml, l, paquet…)',f.unit||'pièce');if(unit===null)return;let place=prompt('Emplacement (Frigo, Congélateur, Armoire)',f.place||'Armoire');if(place===null)return;let date=prompt('Date limite (AAAA-MM-JJ, laisser vide si inconnue)',f.date||'');if(date===null)return;qty=Number(String(qty).replace(',','.'));if(!name.trim()||!Number.isFinite(qty)||qty<0){alert('Nom ou quantité invalide.');return}Object.assign(f,{name:name.trim(),qty,unit:unit.trim()||'pièce',place:place.trim()||'Armoire',date:date.trim()});log('Stock modifié : '+f.name+' ('+qty+' '+f.unit+')');save()}
function bought(id){let c=db.courses.find(x=>String(x.id)===String(id));if(!c)return;let suggested=String(c.qty||'').match(/^\s*([0-9]+(?:[.,][0-9]+)?)\s*(.*)$/);let defaultQty=suggested?suggested[1]:'1';let defaultUnit=suggested&&suggested[2]?suggested[2]:'pièce';let raw=prompt('Quelle quantité as-tu réellement achetée pour « '+c.name+' » ?',defaultQty);if(raw===null)return;let qty=Number(String(raw).replace(',','.'));if(!Number.isFinite(qty)||qty<=0){alert('Indique une quantité supérieure à zéro.');return}let unit=prompt('Unité achetée (g, kg, ml, l, pièce, paquet…)',defaultUnit);if(unit===null)return;unit=unit.trim()||defaultUnit;let place=prompt('Où ranger cet achat ? (Frigo, Congélateur, Armoire)','Armoire');if(place===null)return;let date=prompt('Date limite (AAAA-MM-JJ, facultatif)','');if(date===null)return;let f=db.foods.find(x=>normIngredient(x.name)===normIngredient(c.name)&&norm(x.unit)===norm(unit)&&norm(x.place)===norm(place));if(f){f.qty=(+f.qty||0)+qty;if(date.trim())f.date=date.trim()}else db.foods.push({id:Date.now(),name:c.name,qty,unit,place:place.trim()||'Armoire',date:date.trim(),photo:''});db.courses=db.courses.filter(x=>String(x.id)!==String(id));log('Achat confirmé et stock mis à jour : '+c.name+' ('+qty+' '+unit+')');save()}
function norm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
const ingredientAliases={tomato:'tomate',tomatoes:'tomate',potato:'pomme de terre',potatoes:'pomme de terre',onion:'oignon',onions:'oignon',garlic:'ail',chicken:'poulet',beef:'boeuf',pork:'porc',carrot:'carotte',carrots:'carotte',egg:'oeuf',eggs:'oeuf',milk:'lait',butter:'beurre',cheese:'fromage',flour:'farine',rice:'riz',pasta:'pates',mushroom:'champignon',mushrooms:'champignon',cucumber:'concombre',lettuce:'salade',spinach:'epinard',pepper:'poivron','bell pepper':'poivron',lemon:'citron',lime:'citron vert',cream:'creme',yogurt:'yaourt',yoghurt:'yaourt',apple:'pomme',apples:'pomme',banana:'banane',beans:'haricot',lentils:'lentille',chickpeas:'pois chiche',avocado:'avocat',shrimp:'crevette',prawn:'crevette',salmon:'saumon',tuna:'thon'};
function normIngredient(s){let n=norm(s).replace(/s$/,'');return norm(ingredientAliases[n]||n).replace(/s$/,'')}
function weekStart(){let d=new Date();d.setHours(0,0,0,0);let shift=(d.getDay()+6)%7;d.setDate(d.getDate()-shift);return d}
const dayNames=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];function dateForDay(day){let d=weekStart();d.setDate(d.getDate()+day);return d.toISOString().slice(0,10)}
function dayLabel(day){return new Date(dateForDay(day)+'T12:00:00').toLocaleDateString('fr-CH',{day:'2-digit',month:'2-digit'})}
function qtyFormat(q){return Number.isInteger(q)?String(q):q.toFixed(1)}
function plannedCourses(){
 const remaining=db.foods.map(f=>({name:f.name,qty:+f.qty||0,unit:f.unit}));
 const needs=new Map();const plans=[...db.plans].sort((a,b)=>a.day-b.day||(['Petit-déjeuner','Dîner','Souper'].indexOf(a.meal)-['Petit-déjeuner','Dîner','Souper'].indexOf(b.meal)));
 plans.forEach(p=>{const recipe=db.recipes.find(r=>r.id===p.recipeId);if(!recipe)return;recipe.ingredients.forEach(([name,amount,unit])=>{let need=amount*(+p.servings||2)/2;let matched=remaining.find(f=>normIngredient(f.name)===normIngredient(name)&&norm(f.unit)===norm(unit));let available=matched?.qty||0;let use=Math.min(available,need);if(matched)matched.qty-=use;let deficit=need-use;if(deficit>0){let key=norm(name)+'|'+norm(unit);let prev=needs.get(key)||{name,unit,qty:0,days:[]};prev.qty+=deficit;prev.days.push({day:p.day,meal:p.meal});needs.set(key,prev)}})});
 return [...needs.values()];
}
function regenerateCourses(){const manual=db.courses.filter(c=>c.manual!==false);const generated=plannedCourses().map((n,i)=>({id:'plan-'+i,name:n.name,qty:`${qtyFormat(n.qty)} ${n.unit}`,store:'À choisir',manual:false,when:n.days.map(d=>`${dayNames[d.day]} ${d.meal}`).join(', ')}));db.courses=[...manual,...generated];localStorage.setItem(KEY,JSON.stringify(db))}
function shoppingAdvice(){let missing=plannedCourses();if(!missing.length)return 'Aucune course nécessaire pour le programme enregistré : les stocks couvrent les recettes.';let earliest=Math.min(...db.plans.map(p=>p.day));let firstMissing=missing.flatMap(n=>n.days||[]).sort((a,b)=>a.day-b.day)[0];let day=firstMissing?.day??earliest;return `Suggestion : fais les courses avant le ${dayNames[day]} (${dayLabel(day)}), pour avoir les ingrédients nécessaires à temps.`}
