function recipePhotoId(r){let t=norm((r.name||'')+' '+(r.category||''));let keys=[['pasta|spaghetti|lasagna|lasagne|risotto','pasta'],['salad|salade','salad'],['pizza','pizza'],['burger|hamburger','burger'],['chicken|poulet|pollo','chicken'],['curry|masala|indian|indienne','curry'],['fish|salmon|saumon|poisson','fish'],['seafood|shrimp|prawn|crevette|moules','seafood'],['soup|soupe|velouté','soup'],['rice|riz|paella','rice'],['cake|gâteau|tarte|dessert|cookie|brownie','cake'],['bread|pain|bagel','bread'],['breakfast|pancake|waffle|omelette|egg|œuf','breakfast'],['beef|steak|pork|boeuf|bœuf|viande','meat'],['taco|quesadilla|burrito|mexic','mexican'],['noodle|ramen|stir fry|asian|asiatique','noodle'],['potato|pomme de terre|gratin','potato'],['cheese|fromage|fondue|raclette','cheese'],['vegetable|légume|veggie','vegetable']];for(let [re,k] of keys)if(new RegExp(re,'i').test(t))return FOOD_PHOTOS[k];return FOOD_PHOTOS.default}
