function openRecipePicker(day){pickerDay=day;pickerOrigin='planner';$('pickerback').classList.remove('hidden');$('pickerlabel').textContent=`Ajoute un repas pour ${dayNames[day]}`;show('recipes');$('recipesearch').value='';renderRecipes()}
