function renderRecipes(){let list=$('recipelist');if(!list)return;let query=norm($('recipesearch')?.value||'');let combined=[...db.recipes,...recipeCatalogue.filter(r=>!db.recipes.some(x=>x.id===r.id))];let dl=$('recipesuggestions');if(dl){let q=query;let opts=q.length>=1?combined.filter(r=>norm(r.name+' '+r.ingredients.map(i=>i[0]).join(' ')).includes(q)).slice(0,12):[];dl.innerHTML=opts.map(r=>`<option value="${esc(r.name)}">`).join('')}let fav=db.favorites.map(id=>combined.find(r=>r.id===id)).filter(Boolean);let recipes=combined.filter(r=>!db.favorites.includes(r.id)&&(!query||norm(r.name+' '+r.category+' '+r.ingredients.map(i=>i[0]).join(' ')).includes(query)));if(stockSuggestionMode){let rank=r=>r.ingredients.filter(i=>db.foods.some(f=>normIngredient(f.name)===normIngredient(i[0]))).length/Math.max(1,r.ingredients.length);recipes.sort((a,b)=>rank(b)-rank(a))}let show=recipes.slice(0,60);$('catalogcount').textContent=catalogueLoaded?recipeCatalogue.length+' recettes en ligne':combined.length+' recettes';$('recipecount').textContent=(query?recipes.length:combined.length)+' résultat(s)';list.innerHTML=show.map(r=>{let stock=r.ingredients.filter(i=>db.foods.some(f=>normIngredient(f.name)===normIngredient(i[0]))).length;let isFav=db.favorites.includes(r.id);return `<div class="card recipe-card no-select"><img class="recipe-photo" src="${recipeIllustration(r)}" onerror="recipeImageFallback(this)" loading="lazy" alt="Photo illustrative de ${esc(r.name)}"><div class="recipe-content"><div><b>${esc(r.name)}</b><div class="muted">${r.minutes||'—'} min · ${esc(r.category||'Internationale')}</div><span class="stock-match">${stock}/${r.ingredients.length} ingrédients reconnus en stock</span></div><div class="actions" style="margin-top:12px"><button onclick="openCatalogRecipe('${r.id}')">Voir la recette</button><button class="secondary" onclick="quickFavorite('${r.id}')">♡</button></div></div></div>`}).join('');if(!show.length)list.innerHTML='<div class="card">Aucune recette trouvée. Charge le catalogue ou modifie ta recherche.</div>';renderFavorites();renderPersonalRecipes();}
function renderFavorites(){let el=$('favoritelist');if(!el)return;$('favoritecount').textContent=db.favorites.length;let fav=db.favorites.map(id=>db.recipes.find(x=>x.id===id)||recipeCatalogue.find(x=>x.id===id)).filter(Boolean);el.innerHTML=fav.length?`<div class="recipe-grid">${fav.map(r=>`<div class="card recipe-card"><img class="recipe-photo" src="${recipeIllustration(r)}" onerror="recipeImageFallback(this)" loading="lazy" alt="Photo de ${esc(r.name)}"><div class="recipe-content"><b>${esc(r.name)}</b><div class="muted">${esc(r.category||'Recette')}</div><div class="actions" style="margin-top:10px"><button onclick="openCatalogRecipe('${r.id}')">Ouvrir</button><button class="secondary" onclick="quickFavorite('${r.id}')">♥</button></div></div></div>`).join('')}</div>`:'<p class="muted">Aucun favori pour le moment. Ouvre une recette et touche le cœur pour l’enregistrer.</p>'}
function openCatalogRecipe(id){let r=db.recipes.find(x=>x.id===id)||recipeCatalogue.find(x=>x.id===id);if(!r)return;storeExternalRecipe(r);recipeDetails(id)}
function quickFavorite(id){let r=db.recipes.find(x=>x.id===id)||recipeCatalogue.find(x=>x.id===id);if(!r)return;storeExternalRecipe(r);if(!db.favorites.includes(id))db.favorites.push(id);else db.favorites=db.favorites.filter(x=>x!==id);localStorage.setItem(KEY,JSON.stringify(db));renderRecipes()}
function suggestFromStock(){stockSuggestionMode=true;let pool=[...db.recipes,...recipeCatalogue.filter(r=>!db.recipes.some(x=>x.id===r.id))];let ranked=pool.map(r=>{let have=r.ingredients.filter(i=>db.foods.some(f=>normIngredient(f.name)===normIngredient(i[0]))).length;let expiring=db.foods.filter(f=>days(f.date)<=3&&r.ingredients.some(i=>normIngredient(f.name)===normIngredient(i[0]))).length;return {r,have,total:r.ingredients.length,expiring,score:have/Math.max(1,r.ingredients.length)}}).filter(x=>x.have>0).sort((a,b)=>b.expiring-a.expiring||b.score-a.score).slice(0,8);$('stockrecipehint').textContent=ranked.length?'Suggestions classées selon les ingrédients en stock et les dates proches. Les correspondances restent indicatives, surtout pour les recettes en anglais.':'Ajoute des aliments au stock pour recevoir des suggestions.';$('stockrecipes').innerHTML=ranked.map(x=>`<div class="item"><div style="flex:1"><b>${esc(x.r.name)}</b><div class="muted">${x.have}/${x.total} ingrédients reconnus${x.expiring?' · '+x.expiring+' aliment(s) à utiliser bientôt':''}</div></div><button class="secondary" onclick="openCatalogRecipe('${x.r.id}')">Voir</button></div>`).join('');}
async function searchOnlineRecipes(){let q=$('recipesearch').value.trim();if(q.length<2){$('onlinehint').textContent='Saisis au moins deux caractères.';return}let box=$('onlinerecipes');$('onlinehint').textContent='Recherche en cours…';box.innerHTML='';try{let res=await fetch(`${MEALDB}/search.php?s=${encodeURIComponent(q)}`);if(!res.ok)throw new Error('Service indisponible');let data=await res.json();let meals=Array.isArray(data.meals)?data.meals:[];$('onlinehint').textContent=meals.length?`${meals.length} résultat(s) trouvé(s) dans TheMealDB.`:'Aucune recette trouvée. Essaie un autre terme en anglais ou le nom d’un plat.';box.innerHTML=meals.map(m=>`<div class="item"><img src="${esc(m.strMealThumb||'')}" alt="${esc(m.strMeal)}" style="width:64px;height:56px;object-fit:cover;border-radius:12px"><div style="flex:1"><b>${esc(m.strMeal)}</b><div class="muted">${esc(m.strArea||'Cuisine internationale')} · TheMealDB</div></div><button class="secondary" onclick="openMealDbRecipe('${esc(m.idMeal)}')">Voir</button></div>`).join('')||''}catch(e){$('onlinehint').textContent='La banque en ligne est temporairement inaccessible. Tes recettes locales restent disponibles ; vérifie la connexion puis réessaie.'}}
function parseMeasure(value){let raw=String(value||'').trim();let frac=raw.match(/^(\d+)\s*\/\s*(\d+)/);let m=raw.match(/^(\d+(?:[.,]\d+)?)/);let amount=frac?(+frac[1]/+frac[2]):(m?parseFloat(m[1].replace(',','.')):1);let unit=raw.replace(frac?.[0]||m?.[0]||'','').trim()||'portion';return [amount,unit]}
function mealDbToRecipe(m){let ingredients=[];for(let i=1;i<=20;i++){let name=m['strIngredient'+i]?.trim();if(!name)continue;let [amount,unit]=parseMeasure(m['strMeasure'+i]);ingredients.push([name.toLowerCase(),amount,unit])}let steps=String(m.strInstructions||'').split(/\r?\n+/).map(x=>x.trim()).filter(Boolean);if(steps.length<2)steps=String(m.strInstructions||'').split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean);return {id:'mealdb-'+m.idMeal,name:m.strMeal,minutes:0,category:[m.strCategory,m.strArea].filter(Boolean).join(' · ')||'Internationale',ingredients,steps,nutrition:{},image:m.strMealThumb||'',source:m.strSource||`https://www.themealdb.com/meal/${m.idMeal}`,provider:'TheMealDB'}}
async function openMealDbRecipe(id){$('onlinehint').textContent='Chargement de la recette…';try{let res=await fetch(`${MEALDB}/lookup.php?i=${encodeURIComponent(id)}`);let data=await res.json();if(!data.meals?.[0])throw new Error('Introuvable');let r=mealDbToRecipe(data.meals[0]);let existing=db.recipes.find(x=>x.id===r.id);if(existing)db.recipes=db.recipes.map(x=>x.id===r.id?r:x);else db.recipes.push(r);localStorage.setItem(KEY,JSON.stringify(db));activeRecipeId=r.id;$('detailservings').value=2;$('detailday').innerHTML=dayNames.map((d,i)=>`<option value="${i}">${d} · ${dayLabel(i)}</option>`).join('');$('detailday').value=pickerDay===null?0:pickerDay;document.querySelectorAll('.detailmeal').forEach(x=>x.checked=false);updateRecipeDialog();$('detailmeta').textContent+=' · TheMealDB';let saveBtn=$('favoritebutton');if(saveBtn)saveBtn.textContent=db.favorites.includes(r.id)?'♥ Retirer des favoris':'♡ Ajouter aux favoris';$('recipedialog').showModal()}catch(e){$('onlinehint').textContent='La recette détaillée n’a pas pu être chargée. Réessaie.'}}
function toggleFavorite(){let r=db.recipes.find(x=>x.id===activeRecipeId);if(!r)return;if(!db.favorites.includes(r.id)){db.favorites.push(r.id);log('Favori enregistré hors connexion : '+r.name)}else{db.favorites=db.favorites.filter(x=>x!==r.id);log('Favori retiré : '+r.name)}localStorage.setItem(KEY,JSON.stringify(db));let b=$('favoritebutton');if(b)b.textContent=db.favorites.includes(r.id)?'♥ Retirer des favoris':'♡ Ajouter aux favoris';renderFavorites()}

function toggleRecipeMenu(id){let el=$('menu-'+id);document.querySelectorAll('.more-menu').forEach(m=>{if(m!==el)m.classList.add('hidden')});el?.classList.toggle('hidden')}function closeRecipeMenu(id){$('menu-'+id)?.classList.add('hidden')}
let activeRecipeId=null;function updateRecipeDialog(){let r=db.recipes.find(x=>x.id===activeRecipeId);if(!r)return;let n=Math.max(1,+$('detailservings').value||2);$('detailname').textContent=r.name;$('detailmeta').textContent=`${r.category} · ${r.minutes||'—'} min${r.provider?' · '+r.provider:''}`;let im=$('detailimage');if(im){im.src=recipeIllustration(r);im.onerror=()=>recipeImageFallback(im);im.classList.remove('hidden')}$('detailingredients').innerHTML=r.ingredients.map(i=>`<div class="item"><span>${esc(i[0])}</span><b>${qtyFormat(i[1]*n/2)} ${esc(i[2])}</b></div>`).join('');$('detailsteps').innerHTML=r.steps.map((s,i)=>`<p><b>${i+1}.</b> ${esc(s)}</p>`).join('');let nt=r.nutrition||{};$('detailnutrition').textContent=`${nt.kcal||'—'} kcal · protéines ${nt.protein||'—'} g · glucides ${nt.carbs||'—'} g · lipides ${nt.fat||'—'} g (estimation par personne)`}
function recipeDetails(id){activeRecipeId=id;$('detailservings').value=2;$('detailday').innerHTML=dayNames.map((d,i)=>`<option value="${i}">${d} · ${dayLabel(i)}</option>`).join('');$('detailday').value=pickerDay===null?0:pickerDay;document.querySelectorAll('.detailmeal').forEach(x=>x.checked=false);updateRecipeDialog();$('favoritebutton').textContent=db.favorites.includes(id)?'♥ Retirer des favoris':'♡ Ajouter aux favoris';let del=$('detaildelete');if(del)del.classList.toggle('hidden',!db.recipes.some(x=>x.id===id));$('recipedialog').showModal()}
function closeRecipeDetails(){$('recipedialog').close()}
$('detailservings').addEventListener('input',updateRecipeDialog);$('detailplan').onclick=()=>{let r=db.recipes.find(x=>x.id===activeRecipeId);if(!r)return;let servings=Math.max(1,Math.min(30,+$('detailservings').value||2));let day=+$('detailday').value;let meals=[...document.querySelectorAll('.detailmeal:checked')].map(x=>x.value);if(!meals.length){alert('Choisis au moins un repas : petit-déjeuner, dîner ou souper.');return}meals.forEach(meal=>db.plans.push({id:'p-'+Date.now()+'-'+Math.random().toString(16).slice(2),recipeId:r.id,day,meal,servings}));log(`Recette programmée pour ${dayNames[day]} : ${r.name}`);regenerateCourses();localStorage.setItem(KEY,JSON.stringify(db));closeRecipeDetails();if(pickerOrigin==='planner'&&pickerDay!==null){pickerDay=null;$('pickerback').classList.add('hidden');show('planner')}else{show('recipes')} };
function newRecipe(){openAddRecipe()}
let newRecipePhoto='';let editingRecipeId=null;
function openAddRecipe(){editingRecipeId=null;newRecipePhoto='';['newrecipeurl','newrecipename','newrecipecategory','newrecipeingredients','newrecipesteps'].forEach(id=>$(id).value='');$('newrecipeminutes').value=30;$('newrecipephoto').value='';$('newrecipepreview').classList.add('hidden');$('urlimporthint').textContent='';if($('recipeproxyurl'))$('recipeproxyurl').value=db.recipeProxyUrl||'';$('ocrhint').textContent='OCR dans le navigateur, connexion nécessaire au premier usage.';$('addrecipedialog').showModal()}
function closeAddRecipe(){$('addrecipedialog').close()}
function recipeTextFromJsonLd(data){
 const seen=new Set();function walk(value){if(!value||typeof value!=='object'||seen.has(value))return null;seen.add(value);if(Array.isArray(value)){for(const item of value){const found=walk(item);if(found)return found}return null}
 const types=Array.isArray(value['@type'])?value['@type']:[value['@type']];if(types.some(t=>String(t||'').toLowerCase().split('/').pop()==='recipe'))return value;
 for(const key of ['@graph','mainEntity','mainEntityOfPage','itemListElement','hasPart','subjectOf']){const found=walk(value[key]);if(found)return found}return null}
 return walk(data)
}
function recipeInstructionsText(value){if(!value)return[];if(typeof value==='string')return value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(Array.isArray(value))return value.flatMap(recipeInstructionsText);if(typeof value==='object'){if(value.text)return recipeInstructionsText(value.text);if(value.itemListElement)return recipeInstructionsText(value.itemListElement);if(value.name)return [value.name]}return[]}
function fillRecipeFromStructured(recipe,docTitle=''){
 const name=recipe.name||docTitle.replace(/\s*[|–-].*$/,'').trim();
 const ingredients=Array.isArray(recipe.recipeIngredient)?recipe.recipeIngredient:[];
 const steps=recipeInstructionsText(recipe.recipeInstructions);
 if(!name||(!ingredients.length&&!steps.length))return false;
 $('newrecipename').value=name;
 $('newrecipecategory').value=Array.isArray(recipe.recipeCategory)?recipe.recipeCategory.join(', '):(recipe.recipeCategory||recipe.recipeCuisine||'Importée');
 const mins=String(recipe.totalTime||recipe.cookTime||recipe.prepTime||'').match(/PT(?:(\d+)H)?(?:(\d+)M)?/i);
 $('newrecipeminutes').value=mins?(+(mins[1]||0)*60+ +(mins[2]||0)):30;
 $('newrecipeingredients').value=ingredients.map(x=>{let t=String(x).trim();let m=t.match(/^([\d½¼¾⅓⅔.,/]+)\s*(kg|g|mg|ml|cl|dl|l|c\.?\s*à\s*soupe|c\.?\s*à\s*café|cuillères?[^ ]*|gousses?|paquets?|boîtes?|tranches?)?\s*(.*)$/i);return m?`${(m[3]||t).trim()};${m[1]};${(m[2]||'pièce').trim()}`:`${t};1;à préciser`}).join('\n');
 $('newrecipesteps').value=steps.join('\n');
 const img=Array.isArray(recipe.image)?recipe.image[0]:recipe.image;
 if(typeof img==='string'&&/^https?:/i.test(img))$('urlimporthint').textContent='Recette importée. Vérifie les quantités et les étapes ; la photo du site n’est pas copiée.';
 else $('urlimporthint').textContent='Recette importée. Vérifie les quantités et les étapes.';
 return true;
}
function parseRecipeReaderText(text){
 const raw=String(text||'').replace(/\r/g,'');
 const lines=raw.split('\n').map(x=>x.trim()).filter(Boolean);
 const cleanLine=x=>x.replace(/^\s{0,3}#{1,6}\s*/,'').replace(/^\*\*(.*?)\*\*:?$/,'$1').replace(/\*\*/g,'').replace(/__([^_]+)__/g,'$1').replace(/\s+/g,' ').trim();
 const isHeading=(line,patterns)=>patterns.some(p=>p.test(line));
 const ingHeads=[/^ingr[eé]dients?\b/i,/^ce qu'il faut\b/i,/^pour la recette\b/i,/^liste des ingr[eé]dients\b/i];
 const stepHeads=[/^pr[eé]paration\b/i,/^instructions?\b/i,/^(?:les )?[eé]tapes?\b/i,/^d[eé]roulement\b/i,/^recette\s*:?$/i];
 const stopHeads=[/^nutrition\b/i,/^conseils?\b/i,/^astuces?\b/i,/^notes?\b/i,/^mat[eé]riel\b/i,/^ustensiles?\b/i,/^vous aimerez/i,/^commentaires?\b/i,/^voir aussi\b/i,/^source\b/i,/^publicit[eé]\b/i];
 let title='',section='',ingredients=[],steps=[];
 for(let original of lines){
   let line=cleanLine(original).replace(/^[-*•]\s*/, '').replace(/^\d+[.)]\s*/, '').trim();
   if(!title && (/^title:/i.test(line)||/^titre:/i.test(line)))title=line.replace(/^(?:title|titre):\s*/i,'');
   if(!title && /^#\s+/.test(original))title=cleanLine(original);
   if(isHeading(line,ingHeads)){section='ing';continue}
   if(isHeading(line,stepHeads)){section='steps';continue}
   if(stopHeads.some(p=>p.test(line))){section='';continue}
   if(/^(?:temps|dur[eé]e|cuisson|pr[eé]paration).{0,40}\d+\s*(?:min|h)/i.test(line))continue;
   if(!section)continue;
   if(/^(?:pour\s+\d+\s*(?:personnes?|portions?)|\d+\s*(?:personnes?|portions?))$/i.test(line))continue;
   if(line.length<2||/^(?:ingr[eé]dients?|pr[eé]paration|instructions?)$/i.test(line))continue;
   if(section==='ing')ingredients.push(line); else steps.push(line);
 }
 // Some readers return labelled inline sections rather than separate headings.
 if(!ingredients.length){let m=raw.match(/(?:\*\*)?Ingr[eé]dients?(?:\*\*)?\s*:?([\s\S]*?)(?=(?:\*\*)?Pr[eé]paration|(?:\*\*)?Instructions?|$)/i);if(m)ingredients=m[1].split('\n').map(x=>cleanLine(x).replace(/^[-*•]\s*/, '').trim()).filter(x=>x.length>1)}
 if(!steps.length){let m=raw.match(/(?:\*\*)?(?:Pr[eé]paration|Instructions?|[EÉ]tapes)(?:\*\*)?\s*:?([\s\S]*?)(?=(?:\*\*)?(?:Nutrition|Conseils?|Astuces?|Notes?)|$)/i);if(m)steps=m[1].split('\n').map(x=>cleanLine(x).replace(/^[-*•]\s*/, '').replace(/^\d+[.)]\s*/, '').trim()).filter(x=>x.length>8)}
 ingredients=[...new Set(ingredients)].filter(x=>!/^voir (la )?recette/i.test(x));
 steps=[...new Set(steps)].filter(x=>x.length>8);
 if(!ingredients.length&&!steps.length)return false;
 if(title)$('newrecipename').value=title.replace(/\s*[|–-]\s*(?:Marmiton|750g|Cuisine AZ).*$/i,'').trim();
 $('newrecipecategory').value='Importée depuis un lien';$('newrecipeminutes').value=30;
 $('newrecipeingredients').value=ingredients.map(t=>{let m=t.match(/^([\d½¼¾⅓⅔.,/]+)\s*(kg|g|mg|ml|cl|dl|l|cuillères?\s+à\s+(?:soupe|café)|c\.?\s*à\s*(?:soupe|café)|gousses?|paquets?|boîtes?|tranches?)?\s*(.*)$/i);return m?`${(m[3]||t).trim()};${m[1]};${(m[2]||'pièce').trim()}`:`${t};1;à préciser`}).join('\n');
 $('newrecipesteps').value=steps.map((x,i)=>/^\d+[.)]/.test(x)?x:x).join('\n');
 $('urlimporthint').textContent=`Import partiel : ${ingredients.length} ingrédient(s), ${steps.length} étape(s). Vérifie les quantités avant d’enregistrer.`;
 return true;
}
async function importRecipeUrl(){
 let url=$('newrecipeurl').value.trim();if(!url)return alert('Colle d’abord le lien de la recette.');
 let u;try{u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw new Error('URL non valide')}catch(e){$('urlimporthint').textContent='Le lien n’est pas valide.';return}
 $('urlimporthint').textContent='Analyse de la recette…';$('newrecipeingredients').value='';$('newrecipesteps').value='';db.recipeProxyUrl=$('recipeproxyurl')?.value.trim()||db.recipeProxyUrl||'';localStorage.setItem(KEY,JSON.stringify(db));
 const tryHtml=html=>{let doc=new DOMParser().parseFromString(html,'text/html');for(const tag of doc.querySelectorAll('script[type="application/ld+json"]')){try{let raw=JSON.parse(tag.textContent);let recipe=recipeTextFromJsonLd(raw);if(recipe&&fillRecipeFromStructured(recipe,doc.title))return true}catch(e){}}return parseRecipeReaderText(doc.body?.innerText||doc.body?.textContent||'')};
 // Dedicated proxy first: it fetches the page server-side and returns the original HTML/text.
 const proxy=$('recipeproxyurl')?.value.trim();if(proxy){try{$('urlimporthint').textContent='Lecture via le service Mealora…';let response=await fetch(proxy.replace(/\/$/,'')+'/import?url='+encodeURIComponent(u.href),{headers:{'Accept':'application/json'},signal:AbortSignal.timeout(25000)});if(response.ok){let data=await response.json();if(data.recipe){let r=data.recipe;let structured={name:r.name,recipeIngredient:r.ingredients,recipeInstructions:r.steps,totalTime:r.totalTime||'',recipeCategory:r.category||'Importée',image:r.image||''};if(fillRecipeFromStructured(structured,r.name)){if(r.image&&/^https?:/i.test(r.image))newRecipePhoto='';$('urlimporthint').textContent='Importation via le service Mealora réussie. Vérifie les informations.';return}}if(data.html&&tryHtml(data.html)){$('urlimporthint').textContent='Recette récupérée via le service Mealora. Vérifie les informations.';return}if(data.error)$('urlimporthint').textContent='Service Mealora : '+data.error}else $('urlimporthint').textContent='Le service Mealora a répondu avec une erreur HTTP '+response.status+'.'}catch(err){$('urlimporthint').textContent='Service Mealora indisponible. Tentative des autres méthodes…'}}
 // Direct access is attempted first. Most recipe sites restrict cross-origin browser requests.
 try{let res=await fetch(u.href,{signal:AbortSignal.timeout(12000)});if(res.ok&&tryHtml(await res.text())){$('urlimporthint').textContent='Recette détectée sur le site. Vérifie les quantités et les étapes avant l’enregistrement.';return}}catch(e){}
 // Text reader fallback: supports many sites that expose Recipe schema or readable article text.
 const readers=[
  'https://r.jina.ai/'+u.href,
  'https://r.jina.ai/http://'+u.host+u.pathname+u.search,
  'https://api.allorigins.win/raw?url='+encodeURIComponent(u.href)
 ];
 for(let i=0;i<readers.length;i++){
  try{$('urlimporthint').textContent=`Lecture du site avec une méthode alternative (${i+1}/${readers.length})…`;
   let res=await fetch(readers[i],{headers:{'Accept':'text/plain, text/html'},signal:AbortSignal.timeout(18000)});if(!res.ok)continue;let body=await res.text();
   if(body.length<150)continue;
   if(/<html|<script/i.test(body)&&tryHtml(body)){$('urlimporthint').textContent='Recette importée. Vérifie les informations avant de sauvegarder.';return}
   let title=(body.match(/^(?:Title|Titre):\s*(.+)$/mi)||[])[1]||'';
   if(parseRecipeReaderText(body)){if(title&&!$('newrecipename').value)$('newrecipename').value=title;$('urlimporthint').textContent='Recette détectée. Vérifie les ingrédients et les étapes avant de sauvegarder.';return}
  }catch(e){}
 }
 $('urlimporthint').textContent='Importation impossible : le site bloque la lecture ou ne fournit pas de fiche exploitable. Aucun contenu vide n’a été importé. Tu peux copier-coller les ingrédients et la préparation, ou utiliser la saisie manuelle.';
}
$('newrecipephoto').addEventListener('change',async e=>{let f=e.target.files?.[0];if(!f)return;try{newRecipePhoto=await compressRecipeImage(f);$('newrecipepreview').src=newRecipePhoto;$('newrecipepreview').classList.remove('hidden')}catch(err){alert('Impossible de lire cette image.')}});
function compressRecipeImage(file){return new Promise((resolve,reject)=>{let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let scale=Math.min(1,1200/Math.max(img.width,img.height));let c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.76))};img.onerror=reject;img.src=url})}
async function readRecipePhoto(){let f=$('newrecipephoto').files?.[0];if(!f){alert('Choisis d’abord une photo.');return}try{$('ocrhint').textContent='Chargement du moteur OCR…';if(!window.Tesseract){await new Promise((resolve,reject)=>{let sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)})} $('ocrhint').textContent='Lecture du texte…';let result=await Tesseract.recognize(f,'fra+eng',{logger:m=>{if(m.status==='recognizing text')$('ocrhint').textContent='Lecture : '+Math.round((m.progress||0)*100)+'%'}});let text=result.data.text||'';if(!$('newrecipename').value){let first=text.split('\n').map(x=>x.trim()).find(x=>x.length>3);if(first)$('newrecipename').value=first}if(!$('newrecipeingredients').value)$('newrecipeingredients').value=text;$('ocrhint').textContent='Texte reconnu. Vérifie et répartis les ingrédients et les étapes dans les champs correspondants.'}catch(e){$('ocrhint').textContent='Lecture automatique indisponible. Tu peux conserver la photo et saisir les informations à la main.'}}
function savePersonalRecipe(){let name=$('newrecipename').value.trim();if(!name)return alert('Indique le nom de la recette.');let ingredients=$('newrecipeingredients').value.split('\n').map(line=>line.split(';').map(x=>x.trim())).filter(a=>a.length>=3&&a[0]&&Number(a[1])>0).map(a=>[a[0],Number(a[1]),a[2]]);let steps=$('newrecipesteps').value.split('\n').map(x=>x.trim()).filter(Boolean);if($('newrecipeurl').value.trim()&&(!ingredients.length||!steps.length)){return alert('La recette importée est incomplète. Vérifie et complète les ingrédients et la préparation avant de l’enregistrer.')}let sourceUrl=$('newrecipeurl').value.trim();let previous=editingRecipeId?db.recipes.find(x=>x.id===editingRecipeId):null;let r={...(previous||{}),id:editingRecipeId||'custom-'+Date.now(),name,minutes:Math.max(0,+$('newrecipeminutes').value||0),category:$('newrecipecategory').value.trim()||'Personnelle',ingredients,steps,nutrition:previous?.nutrition||{},image:newRecipePhoto||'',sourceUrl,provider:sourceUrl?'Recette personnelle · lien source':'Recette personnelle',personal:true};if(editingRecipeId)db.recipes=db.recipes.map(x=>x.id===editingRecipeId?r:x);else db.recipes.push(r);log((editingRecipeId?'Recette personnelle modifiée : ':'Recette personnelle ajoutée : ')+name);regenerateCourses();localStorage.setItem(KEY,JSON.stringify(db));closeAddRecipe();render();$('personalrecipes')?.scrollIntoView({behavior:'smooth',block:'start'})}
function renderPersonalRecipes(){let el=$('personalrecipes');if(!el)return;let items=db.recipes.filter(r=>r.personal||String(r.id).startsWith('custom-'));el.innerHTML=items.map(r=>`<div class="card recipe-card"><img class="recipe-photo" src="${r.image||recipeIllustration(r)}" onerror="recipeImageFallback(this)" loading="lazy" alt="Photo de ${esc(r.name)}"><div class="recipe-content"><b>${esc(r.name)}</b><div class="muted">${esc(r.category||'Personnelle')} · ${r.minutes||'—'} min</div>${r.sourceUrl?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Voir la source</a>`:''}<div class="actions" style="margin-top:10px"><button onclick="recipeDetails('${r.id}')">Voir la recette</button><button class="secondary" onclick="editRecipe('${r.id}')">Modifier</button></div></div></div>`).join('')||'<p class="muted">Tes recettes ajoutées apparaîtront ici.</p>'}
function editRecipe(id){let r=db.recipes.find(x=>x.id===id);if(!r)return;openAddRecipe();editingRecipeId=id;$('newrecipename').value=r.name;$('newrecipecategory').value=r.category||'';$('newrecipeminutes').value=r.minutes||30;$('newrecipeurl').value=r.sourceUrl||'';$('newrecipeingredients').value=(r.ingredients||[]).map(i=>i.join(';')).join('\n');$('newrecipesteps').value=(r.steps||[]).join('\n');newRecipePhoto=r.image||'';if(newRecipePhoto){$('newrecipepreview').src=newRecipePhoto;$('newrecipepreview').classList.remove('hidden')}let save=$('addrecipedialog').querySelector('.actions button');save.textContent='Enregistrer les modifications';save.onclick=savePersonalRecipe}
function deleteRecipe(id){let r=db.recipes.find(x=>x.id===id);if(!r||!confirm(`Supprimer « ${r.name} » et ses programmations ?`))return;db.recipes=db.recipes.filter(x=>x.id!==id);db.plans=db.plans.filter(p=>p.recipeId!==id);db.favorites=db.favorites.filter(x=>x!==id);if($('recipedialog')?.open)$('recipedialog').close();log('Recette supprimée : '+r.name);regenerateCourses();save()}
function removePlan(id){db.plans=db.plans.filter(p=>p.id!==id);log('Programmation de repas retirée');regenerateCourses();save()}
function computedShoppingDate(){let missing=plannedCourses();if(!missing.length)return '';let first=missing.flatMap(n=>n.days||[]).sort((a,b)=>a.day-b.day)[0];if(!first)return '';let d=new Date(dateForDay(first.day)+'T12:00:00');d.setDate(d.getDate()-1);let today=new Date();today.setHours(0,0,0,0);if(d<today)d=today;return d.toISOString().slice(0,10)}function suggestShoppingDate(){db.shoppingDate=computedShoppingDate();if(!db.shoppingDate)db.shoppingDate=dateForDay(0);localStorage.setItem(KEY,JSON.stringify(db));render();$('shoppingdate').value=db.shoppingDate}function saveShoppingDate(){db.shoppingDate=$('shoppingdate').value;log('Date des courses modifiée : '+(db.shoppingDate||'non définie'));localStorage.setItem(KEY,JSON.stringify(db));render()}function displayShoppingDate(){let d=db.shoppingDate||computedShoppingDate();if(!d)return 'À définir';return new Date(d+'T12:00:00').toLocaleDateString('fr-CH',{weekday:'short',day:'2-digit',month:'2-digit'})}
function planIssues(){const remaining=db.foods.map(f=>({name:f.name,qty:+f.qty||0,unit:f.unit}));const issues=[];[...db.plans].sort((a,b)=>a.day-b.day).forEach(p=>{let recipe=db.recipes.find(r=>r.id===p.recipeId);if(!recipe)return;let deficits=[];recipe.ingredients.forEach(([name,amount,unit])=>{let need=amount*(+p.servings||2)/2;let match=remaining.find(f=>normIngredient(f.name)===normIngredient(name)&&norm(f.unit)===norm(unit));let avail=match?.qty||0;let use=Math.min(avail,need);if(match)match.qty-=use;if(need-use>0.001)deficits.push(`${name}: ${qtyFormat(need-use)} ${unit}`)});if(deficits.length)issues.push({p,recipe,deficits})});return issues}
function alternatives(){let remaining=db.foods.map(f=>({name:f.name,qty:+f.qty||0,unit:f.unit}));return db.recipes.map(r=>{let missing=0;r.ingredients.forEach(([name,amount,unit])=>{let f=remaining.find(x=>normIngredient(x.name)===normIngredient(name)&&norm(x.unit)===norm(unit));if((f?.qty||0)<amount)missing++});return {r,missing}}).filter(x=>x.missing===0).sort((a,b)=>a.r.minutes-b.r.minutes).slice(0,3)}
function renderPlanner(){
 let html=dayNames.map((d,i)=>{let entries=db.plans.filter(p=>p.day===i);let meals=['Petit-déjeuner','Dîner','Souper'];return `<div class="card day-card"><div class="day-top"><div><div class="day-title">${d}</div><div class="muted">${dayLabel(i)}</div></div><button class="secondary" onclick="openRecipePicker(${i})">＋ Ajouter</button></div>${meals.map(meal=>{let list=entries.filter(p=>p.meal===meal);return `<div class="meal-slot"><strong>${meal}</strong>${list.map(p=>{let r=db.recipes.find(x=>x.id===p.recipeId);return `<div class="item"><div><b>${esc(r?.name||'Recette retirée')}</b><div class="muted">${p.servings} personne(s)</div></div><button class="ghost" onclick="removePlan('${p.id}')" aria-label="Retirer">✕</button></div>`}).join('')||'<div class="empty-slot">Aucun repas prévu</div>'}</div>`}).join('')}</div>`}).join('');$('weekplan').innerHTML=html;
 let issues=planIssues();$('missingplans').innerHTML=issues.length?issues.map(x=>`<p><b>${esc(dayNames[x.p.day])} · ${esc(x.p.meal)} — ${esc(x.recipe.name)}</b><br><span class="muted">À acheter : ${esc(x.deficits.join(', '))}</span></p>`).join(''):'<p class="muted">Aucune recette programmée ne manque d’ingrédients.</p>';
 let alt=alternatives();$('alternatives').innerHTML=alt.length?alt.map(x=>`<p><b>${esc(x.r.name)}</b> · ${x.r.minutes} min · ingrédients disponibles<br><button class="secondary" onclick="recipeDetails('${x.r.id}')">Voir cette alternative</button></p>`).join(''):'<p class="muted">Ajoute des aliments aux stocks pour obtenir des alternatives.</p>';
 if($('shoppingdate'))$('shoppingdate').value=db.shoppingDate||computedShoppingDate();if($('shoppingdatehint'))$('shoppingdatehint').textContent=(db.shoppingDate||computedShoppingDate())?`Date proposée/enregistrée : ${displayShoppingDate()}`:'Aucune date proposée (programme sans achat nécessaire).'
}
function render(){regenerateCourses();let urgent=db.foods.filter(f=>days(f.date)<=3);$('count').textContent=db.foods.length;$('urgent').textContent=urgent.length;$('coursecount').textContent=db.courses.length;let total=db.spend.filter(s=>new Date(s.at).getMonth()===new Date().getMonth()).reduce((a,s)=>a+s.n,0);$('budgetview').textContent='CHF '+total.toFixed(0);$('shoppingdateview').textContent=displayShoppingDate();$('budget').value=db.budget||'';let issuesDashboard=planIssues();$('dashboardmissing').innerHTML=issuesDashboard.length?issuesDashboard.map(x=>`<div class="item"><div><b>${esc(dayNames[x.p.day])} · ${esc(x.p.meal)} — ${esc(x.recipe.name)}</b><div class="muted">À acheter : ${esc(x.deficits.join(', '))}</div></div></div>`).join(''):'Aucune recette planifiée ne nécessite d’achat.';$('alerts').innerHTML=urgent.length?urgent.map(f=>`<div class="item"><b>${esc(f.name)}</b><span class="pill">${days(f.date)<0?'Dépassé':days(f.date)===0?'Aujourd’hui':'Dans '+days(f.date)+' j'}</span></div>`).join(''):'Rien d’urgent. Tes aliments sont tranquilles !';$('foodlist').innerHTML=['Frigo','Congélateur','Armoire'].map(p=>`<div class="sectionhead"><h2>${p}</h2></div><div class="card">${db.foods.filter(f=>f.place===p).map(f=>`<div class="item">${f.photo?`<img src="${f.photo}" style="width:54px;height:54px;object-fit:cover;border-radius:10px">`:''}<div style="flex:1"><b>${esc(f.name)}</b><div class="muted">${esc(f.qty)} ${esc(f.unit)} · ${f.date||'Date non indiquée'}</div></div><button class="secondary" onclick="editFood('${f.id}')">Modifier</button><button class="secondary" onclick="removeFood('${f.id}')">Retirer</button></div>`).join('')||'<span class="muted">Aucun aliment</span>'}</div>`).join('');$('courselist').innerHTML=db.courses.map(c=>`<div class="card item"><div><b>${esc(c.name)}</b><div class="muted">${esc(c.qty)} · ${esc(c.store)}${c.when?'<br>Pour : '+esc(c.when):''}${c.manual?'':'<br><span class="pill">Calculé selon le programme</span>'}</div></div><button onclick="bought('${esc(String(c.id))}')">Acheté</button></div>`).join('')||'<p class="muted">Ta liste est vide.</p>';$('historylist').innerHTML=db.history.length?db.history.map(h=>`<div class="item"><span>${esc(h.t)}</span><small class="muted">${esc(h.at)}</small></div>`).join(''):'Aucune activité enregistrée.';renderRecipes();renderPlanner()}
$('budget').addEventListener('change',()=>save());
render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
